  if (order === 0) {
    card.style.transform = "translateY(0) scale(1)";
    card.style.opacity = "1";
    card.style.zIndex = "4";
  }

  if (order === 1) {
    card.style.transform = "translateY(24px) scale(0.96)";
    card.style.opacity = "0.66";
    card.style.zIndex = "3";
  }

  if (order === 2) {
    card.style.transform = "translateY(48px) scale(0.92)";
    card.style.opacity = "0.4";
    card.style.zIndex = "2";
  }

  card.innerHTML = `
    <div class="game-backdrop" style="background:${game.gradient}">
      <div class="backdrop-pattern"></div>
      <div class="game-overlay"></div>
    </div>
    <div class="game-hud">
      <div class="hint-pill">${game.hint}</div>
      <div class="time-bar"><span style="width:${game.timeLeft}%"></span></div>
      <div class="game-meta">
        <div class="creator">${game.creator}</div>
        <h2 class="game-title">${game.title}</h2>
        <p class="game-desc">${game.desc}</p>
        <div class="game-social">
          <span class="social-item">❤ ${game.likes}</span>
          <span class="social-item">💬 ${game.comments}</span>
          <span class="social-item">↗ ${game.share}</span>
        </div>
      </div>
    </div>
  `;

  card.addEventListener("dblclick", (event) => {
    burstLike(event.clientX, event.clientY);
  });

  card.addEventListener("touchstart", (event) => {
    const touch = event.touches[0];
    holdTimer = setTimeout(() => {
      burstLike(touch.clientX, touch.clientY, "⭐");
    }, 520);
  });

  card.addEventListener("touchend", () => {
    clearTimeout(holdTimer);
  });

  return card;
}

function renderFeed() {
  feedStage.innerHTML = "";

  [0, 1, 2].forEach((offset) => {
    const gameIndex = clampGameIndex(currentIndex + offset);
    const card = createGameCard(games[gameIndex], offset);
    feedStage.appendChild(card);
  });
}

function switchGame(direction) {
  currentIndex = clampGameIndex(currentIndex + direction);
  renderFeed();
}

function burstLike(x, y, icon = "❤") {
  const el = document.createElement("div");
  el.className = "like-burst";
  el.textContent = icon;
  el.style.left = `${x}px`;
  el.style.top = `${y}px`;
  feedStage.appendChild(el);
  setTimeout(() => el.remove(), 760);
}

function mountSwipeEvents() {
  feedStage.addEventListener("touchstart", (event) => {
    startY = event.touches[0].clientY;
  });

  feedStage.addEventListener("touchend", (event) => {
    const endY = event.changedTouches[0].clientY;
    const delta = endY - startY;
    if (Math.abs(delta) < 45) return;
    if (delta < 0) switchGame(1);
    if (delta > 0) switchGame(-1);
  });
}

function renderChips() {
  styleChipsContainer.innerHTML = styles
    .map(
      (item) =>
        `<button class="chip ${item.name === activeStyle ? "active" : ""}" data-type="${item.type}" data-value="${item.name}">${item.name}</button>`
    )
    .join("");

  difficultyChipsContainer.innerHTML = difficulties
    .map(
      (item) =>
        `<button class="chip ${item.name === activeDifficulty ? "active" : ""}" data-type="${item.type}" data-value="${item.name}">${item.name}</button>`
    )
    .join("");
}

function bindChipEvents() {
  [styleChipsContainer, difficultyChipsContainer].forEach((container) => {
    container.addEventListener("click", (event) => {
      const target = event.target;
      if (!(target instanceof HTMLElement)) return;
      if (!target.classList.contains("chip")) return;
      const type = target.dataset.type;
      const value = target.dataset.value;
      if (!type || !value) return;

      if (type === "style") activeStyle = value;
      if (type === "difficulty") activeDifficulty = value;
      renderChips();
    });
  });
}

