class BaseMiniGame {
  constructor(canvas, statsEl) {
    this.canvas = canvas;
    this.ctx = canvas.getContext("2d");
    this.statsEl = statsEl;
    this.running = false;
    this.score = 0;
    this.duration = 30;
    this.startTs = 0;
    this.lastTs = 0;
    this.raf = null;
  }

  start() {
    this.running = true;
    this.score = 0;
    this.startTs = 0;
    this.lastTs = 0;
    this.loop = this.loop.bind(this);
    this.raf = requestAnimationFrame(this.loop);
  }

  stop() {
    this.running = false;
    if (this.raf) cancelAnimationFrame(this.raf);
  }

  loop(ts) {
    if (!this.running) return;
    if (!this.startTs) {
      this.startTs = ts;
      this.lastTs = ts;
    }

    const dt = (ts - this.lastTs) / 1000;
    const elapsed = (ts - this.startTs) / 1000;
    const remain = Math.max(0, this.duration - elapsed);
    this.lastTs = ts;

    this.update(dt, remain);
    this.draw(remain);
    this.statsEl.textContent = `分数 ${this.score} · ${Math.ceil(remain)}s`;

    if (remain <= 0) {
      this.running = false;
      this.onEnd();
      return;
    }

    this.raf = requestAnimationFrame(this.loop);
  }

  onEnd() {
    const { ctx, canvas } = this;
    ctx.fillStyle = "rgba(4, 10, 19, 0.62)";
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = "#f4f9ff";
    ctx.font = "700 22px Outfit";
    ctx.fillText("本局结束", canvas.width / 2 - 44, canvas.height / 2 - 8);
    ctx.font = "13px Noto Sans SC";
    ctx.fillText(`得分 ${this.score}`, canvas.width / 2 - 26, canvas.height / 2 + 16);
  }
}

class TapCollectorGame extends BaseMiniGame {
  start() {
    this.targets = [];
    this.spawnDelay = 0;
    super.start();
  }

  spawnTarget() {
    this.targets.push({
      x: 20 + Math.random() * (this.canvas.width - 40),
      y: this.canvas.height + 12,
      r: 12 + Math.random() * 8,
      vy: 50 + Math.random() * 40,
      life: 1
    });
  }

  pointer(x, y) {
    if (!this.running) return;
    let hit = false;
    this.targets = this.targets.filter((t) => {
      const dx = x - t.x;
      const dy = y - t.y;
      const ok = dx * dx + dy * dy < t.r * t.r;
      if (ok) {
        hit = true;
        return false;
      }
      return true;
    });

    if (hit) this.score += 1;
  }

  update(dt) {
    this.spawnDelay -= dt;
    if (this.spawnDelay <= 0) {
      this.spawnDelay = Math.max(0.18, 0.5 - this.score * 0.01);
      this.spawnTarget();
    }

    this.targets.forEach((t) => {
      t.y -= t.vy * dt;
      t.life -= dt * 0.2;
    });
    this.targets = this.targets.filter((t) => t.y > -20 && t.life > 0);
  }

  draw() {
    const { ctx, canvas } = this;
    ctx.fillStyle = "#0b1b31";
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.fillStyle = "rgba(255,255,255,0.08)";
    for (let x = 0; x < canvas.width; x += 24) {
      ctx.fillRect(x, 0, 1, canvas.height);
    }

    this.targets.forEach((t) => {
      const g = ctx.createRadialGradient(t.x, t.y, 1, t.x, t.y, t.r);
      g.addColorStop(0, "#fff7ca");
      g.addColorStop(1, "#ff9f55");
      ctx.fillStyle = g;
      ctx.beginPath();
      ctx.arc(t.x, t.y, t.r, 0, Math.PI * 2);
      ctx.fill();
    });
  }
}

class DodgeLaneGame extends BaseMiniGame {
  start() {
    this.playerLane = 1;
    this.obstacles = [];
    this.spawnDelay = 0;
    this.hit = false;
    super.start();
  }

  move(direction) {
    if (!this.running) return;
    this.playerLane = Math.max(0, Math.min(2, this.playerLane + direction));
  }

  pointer(x) {
    if (!this.running) return;
    this.move(x < this.canvas.width / 2 ? -1 : 1);
  }

  update(dt) {
    if (this.hit) return;

    this.spawnDelay -= dt;
    if (this.spawnDelay <= 0) {
      this.spawnDelay = Math.max(0.2, 0.62 - this.score * 0.012);
      this.obstacles.push({ lane: Math.floor(Math.random() * 3), y: -24, passed: false });
    }

    const speed = 130 + this.score * 3;
    this.obstacles.forEach((obs) => {
      obs.y += speed * dt;
      if (!obs.passed && obs.y > this.canvas.height - 30) {
        obs.passed = true;
        this.score += 1;
      }
      if (Math.abs(obs.y - (this.canvas.height - 24)) < 12 && obs.lane === this.playerLane) {
        this.hit = true;
      }
    });

    this.obstacles = this.obstacles.filter((obs) => obs.y < this.canvas.height + 30);

    if (this.hit) {
      this.running = false;
      this.onEnd();
    }
  }

  draw() {
    const { ctx, canvas } = this;
    const laneW = canvas.width / 3;
    ctx.fillStyle = "#0a1a2d";
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    for (let i = 1; i < 3; i += 1) {
      ctx.strokeStyle = "rgba(255,255,255,0.12)";
      ctx.beginPath();
      ctx.moveTo(i * laneW, 0);
      ctx.lineTo(i * laneW, canvas.height);
      ctx.stroke();
    }

    this.obstacles.forEach((obs) => {
      ctx.fillStyle = "#ff7f52";
      ctx.fillRect(obs.lane * laneW + laneW * 0.3, obs.y, laneW * 0.4, 20);
    });

    ctx.fillStyle = this.hit ? "#ff5f6b" : "#7cf4ce";
    ctx.fillRect(this.playerLane * laneW + laneW * 0.28, canvas.height - 24, laneW * 0.44, 16);
  }
}

class BubblePopGame extends BaseMiniGame {
  start() {
    this.grid = [];
    this.phase = 0;
    this.buildGrid();
    super.start();
  }

  buildGrid() {
    this.grid = [];
    const cols = 5;
    const rows = 4;
    const spacingX = this.canvas.width / (cols + 1);
    const spacingY = this.canvas.height / (rows + 1);

    for (let y = 1; y <= rows; y += 1) {
      for (let x = 1; x <= cols; x += 1) {
        this.grid.push({
          x: spacingX * x,
          y: spacingY * y,
          r: 14,
          alive: true,
          hue: Math.floor(Math.random() * 360)
        });
      }
    }
  }

  pointer(px, py) {
    if (!this.running) return;
    this.grid.forEach((b) => {
      if (!b.alive) return;
      const dx = px - b.x;
      const dy = py - b.y;
      if (dx * dx + dy * dy <= b.r * b.r) {
        b.alive = false;
        this.score += 1;
      }
    });

    const remain = this.grid.some((b) => b.alive);
    if (!remain) this.buildGrid();
  }

  update(dt) {
    this.phase += dt * 2.6;
  }

  draw() {
    const { ctx, canvas } = this;
    ctx.fillStyle = "#111e33";
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    this.grid.forEach((b, idx) => {
      if (!b.alive) return;
      const r = b.r + Math.sin(this.phase + idx * 0.4) * 1.6;
      ctx.fillStyle = `hsla(${b.hue}, 86%, 64%, 0.88)`;
      ctx.beginPath();
      ctx.arc(b.x, b.y, r, 0, Math.PI * 2);
      ctx.fill();

      ctx.fillStyle = "rgba(255,255,255,0.26)";
      ctx.beginPath();
      ctx.arc(b.x - 4, b.y - 4, r * 0.28, 0, Math.PI * 2);
      ctx.fill();
    });
  }
}

function createMiniGame(gameType, canvas, statsEl) {
  if (gameType === "tap") return new TapCollectorGame(canvas, statsEl);
  if (gameType === "dodge") return new DodgeLaneGame(canvas, statsEl);
  return new BubblePopGame(canvas, statsEl);
}

function bootMiniGame(card) {
  const canvas = card.querySelector("[data-canvas]");
  const stats = card.querySelector("[data-stats]");
  const action = card.querySelector("[data-action]");
  const tip = card.querySelector("[data-tip]");
  const gameType = card.dataset.gameType;

  const runtime = createMiniGame(gameType, canvas, stats);

  const resolvePoint = (event) => {
    const rect = canvas.getBoundingClientRect();
    const source = event.touches ? event.touches[0] : event;
    return {
      x: ((source.clientX - rect.left) / rect.width) * canvas.width,
      y: ((source.clientY - rect.top) / rect.height) * canvas.height
    };
  };

  const onPointer = (event) => {
    const point = resolvePoint(event);
    runtime.pointer(point.x, point.y);
  };

  canvas.addEventListener("pointerdown", onPointer);
  canvas.addEventListener("touchstart", onPointer, { passive: true });

  const startGame = () => {
    runtime.start();
    action.textContent = "重开";
    tip.textContent = gameType === "dodge" ? "点击左/右半屏切换跑道" : "点击游戏区持续得分";
  };

  action.addEventListener("click", startGame);
  startGame();

  return {
    stop() {
      runtime.stop();
      canvas.replaceWith(canvas.cloneNode(true));
      action.replaceWith(action.cloneNode(true));
    }
  };
}

function renderFeed() {
  if (activeRuntime) {
    activeRuntime.stop();
    activeRuntime = null;
  }

  feedStage.innerHTML = "";
  [0, 1, 2].forEach((offset) => {
    const gameIndex = clampGameIndex(currentIndex + offset);
    const card = createGameCard(games[gameIndex], offset);
    feedStage.appendChild(card);

    if (offset === 0) {
      activeRuntime = bootMiniGame(card);
    } else {
      const previewCanvas = card.querySelector("[data-canvas]");
      drawStandbyPreview(previewCanvas, games[gameIndex].gameType);
    }
  });
}

function switchGame(direction) {
  currentIndex = clampGameIndex(currentIndex + direction);
