function drawStandbyPreview(canvas, type) {
  const ctx = canvas.getContext("2d");
  const w = canvas.width;
  const h = canvas.height;
  const bg = ctx.createLinearGradient(0, 0, w, h);
  bg.addColorStop(0, "#10213a");
  bg.addColorStop(1, "#0a1728");
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, w, h);

  ctx.globalAlpha = 0.2;
  for (let i = 0; i < 10; i += 1) {
    ctx.fillStyle = i % 2 ? "#3ad6f6" : "#ff9a4e";
    ctx.beginPath();
    ctx.arc((w / 10) * i + 16, 26 + ((i % 3) * 24), 8 + (i % 3), 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.globalAlpha = 1;

  const labels = {
    tap: "点击收集",
    dodge: "反应躲避",
    bubble: "解压爆破"
  };

  ctx.fillStyle = "rgba(245, 250, 255, 0.92)";
  ctx.font = "700 24px Outfit";
  ctx.fillText(labels[type] || "小游戏", 18, h / 2 - 6);
  ctx.font = "13px Noto Sans SC";
  ctx.fillStyle = "rgba(229, 238, 255, 0.84)";
  ctx.fillText("切到前台即可开玩", 18, h / 2 + 20);
}

