class BubblePopGame extends BaseMiniGame {
  start() {
    this.grid = [];
    this.phase = 0;
    this.buildGrid();
    super.start();
  }

  buildGrid() {
    this.grid = [];
    const cols = 5;
    const rows = 4;
    const spacingX = this.canvas.width / (cols + 1);
    const spacingY = this.canvas.height / (rows + 1);

    for (let y = 1; y <= rows; y += 1) {
      for (let x = 1; x <= cols; x += 1) {
        this.grid.push({
          x: spacingX * x,
          y: spacingY * y,
          r: 14,
          alive: true,
          hue: Math.floor(Math.random() * 360)
        });
      }
    }
  }

  pointer(px, py) {
    if (!this.running) return;
    this.grid.forEach((b) => {
      if (!b.alive) return;
      const dx = px - b.x;
      const dy = py - b.y;
      if (dx * dx + dy * dy <= b.r * b.r) {
        b.alive = false;
        this.score += 1;
      }
    });

    const remain = this.grid.some((b) => b.alive);
    if (!remain) this.buildGrid();
  }

  update(dt) {
    this.phase += dt * 2.6;
  }

  draw() {
    const { ctx, canvas } = this;
    ctx.fillStyle = "#111e33";
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    this.grid.forEach((b, idx) => {
      if (!b.alive) return;
      const r = b.r + Math.sin(this.phase + idx * 0.4) * 1.6;
      ctx.fillStyle = `hsla(${b.hue}, 86%, 64%, 0.88)`;
      ctx.beginPath();
      ctx.arc(b.x, b.y, r, 0, Math.PI * 2);
      ctx.fill();

      ctx.fillStyle = "rgba(255,255,255,0.26)";
      ctx.beginPath();
      ctx.arc(b.x - 4, b.y - 4, r * 0.28, 0, Math.PI * 2);
      ctx.fill();
    });
  }
}

function createMiniGame(gameType, canvas, statsEl) {
  if (gameType === "tap") return new TapCollectorGame(canvas, statsEl);
  if (gameType === "dodge") return new DodgeLaneGame(canvas, statsEl);
  return new BubblePopGame(canvas, statsEl);
}

function bootMiniGame(card) {
  const canvas = card.querySelector("[data-canvas]");
  const stats = card.querySelector("[data-stats]");
  const action = card.querySelector("[data-action]");
  const tip = card.querySelector("[data-tip]");
  const gameType = card.dataset.gameType;

  const runtime = createMiniGame(gameType, canvas, stats);

  const resolvePoint = (event) => {
    const rect = canvas.getBoundingClientRect();
    const source = event.touches ? event.touches[0] : event;
    return {
      x: ((source.clientX - rect.left) / rect.width) * canvas.width,
      y: ((source.clientY - rect.top) / rect.height) * canvas.height
    };
  };

  const onPointer = (event) => {
    const point = resolvePoint(event);
    runtime.pointer(point.x, point.y);
  };

  canvas.addEventListener("pointerdown", onPointer);
  canvas.addEventListener("touchstart", onPointer, { passive: true });

  const startGame = () => {
    runtime.start();
    action.textContent = "重开";
    tip.textContent = gameType === "dodge" ? "点击左/右半屏切换跑道" : "点击游戏区持续得分";
  };

  action.addEventListener("click", startGame);
  startGame();

  return {
    stop() {
      runtime.stop();
      canvas.replaceWith(canvas.cloneNode(true));
      action.replaceWith(action.cloneNode(true));
    }
  };
}

function renderFeed() {
  if (activeRuntime) {
    activeRuntime.stop();
    activeRuntime = null;
  }

  feedStage.innerHTML = "";
  [0, 1, 2].forEach((offset) => {
    const gameIndex = clampGameIndex(currentIndex + offset);
    const card = createGameCard(games[gameIndex], offset);
    feedStage.appendChild(card);

    if (offset === 0) {
      activeRuntime = bootMiniGame(card);
    } else {
      const previewCanvas = card.querySelector("[data-canvas]");
      drawStandbyPreview(previewCanvas, games[gameIndex].gameType);
    }
  });
}

function switchGame(direction) {
  currentIndex = clampGameIndex(currentIndex + direction);
  renderFeed();
}

function burstLike(x, y, icon = "❤") {
  const el = document.createElement("div");
  el.className = "like-burst";
  el.textContent = icon;
  el.style.left = `${x}px`;
  el.style.top = `${y}px`;
  feedStage.appendChild(el);
  setTimeout(() => el.remove(), 760);
}

function mountSwipeEvents() {
  feedStage.addEventListener("touchstart", (event) => {
    startY = event.touches[0].clientY;
  });

  feedStage.addEventListener("touchend", (event) => {
    const endY = event.changedTouches[0].clientY;
    const delta = endY - startY;
    if (Math.abs(delta) < 48) return;
    if (delta < 0) switchGame(1);
    if (delta > 0) switchGame(-1);
  });
}

function renderChips() {
  styleChipsContainer.innerHTML = styles
    .map(
      (item) =>
        `<button class="chip ${item.name === activeStyle ? "active" : ""}" data-type="${item.type}" data-value="${item.name}">${item.name}</button>`
    )
    .join("");

  difficultyChipsContainer.innerHTML = difficulties
    .map(
      (item) =>
        `<button class="chip ${item.name === activeDifficulty ? "active" : ""}" data-type="${item.type}" data-value="${item.name}">${item.name}</button>`
    )
    .join("");
}

function bindChipEvents() {
  [styleChipsContainer, difficultyChipsContainer].forEach((container) => {
    container.addEventListener("click", (event) => {
      const target = event.target;
      if (!(target instanceof HTMLElement)) return;
      if (!target.classList.contains("chip")) return;
      const type = target.dataset.type;
      const value = target.dataset.value;
      if (!type || !value) return;

      if (type === "style") activeStyle = value;
      if (type === "difficulty") activeDifficulty = value;
      renderChips();
    });
  });
}

function updatePreviewTags(tags) {
  previewTags.innerHTML = tags.map((tag) => `<span>${tag}</span>`).join("");
}

function simulateGeneration() {
  const prompt = promptInput.value.trim();
  if (!prompt) {
    generatorPhase.textContent = "先输入一个创意点子";
    generatorEta.textContent = "例如：做一个猫咪接鱼的小游戏";
    return;
  }

  generateBtn.disabled = true;
  generateBtn.textContent = "生成中...";
  generatorProgress.style.setProperty("--progress-width", "0%");

  const phases = [
    { progress: 14, phase: "AI 正在理解玩法目标", eta: "意图拆解 3 秒" },
    { progress: 40, phase: "生成核心规则与胜负条件", eta: "规则构建中" },
    { progress: 76, phase: "组合画面与交互反馈", eta: "准备预览" },
    { progress: 100, phase: "生成完成，可试玩并发布", eta: "总耗时约 30 秒（Demo: 6 秒）" }
  ];

  phases.forEach((step, index) => {
    setTimeout(() => {
      generatorProgress.style.setProperty("--progress-width", `${step.progress}%`);
      generatorPhase.textContent = step.phase;
      generatorEta.textContent = step.eta;

      if (step.progress === 100) {
        const generatedName = prompt.length > 18 ? `${prompt.slice(0, 18)}...` : prompt;
        previewTitle.textContent = generatedName;
        previewDesc.textContent = `玩法风格：${activeStyle}，难度：${activeDifficulty}。建议单局时长控制在 45-90 秒，鼓励“再来一局”。`;
        updatePreviewTags(["点击", "躲避", "收集", activeStyle, activeDifficulty]);
        generateBtn.disabled = false;
        generateBtn.textContent = "重新生成";
      }
    }, 1500 * index);
  });
}

function renderDiscover() {
  const categories = ["益智", "动作", "解压", "创意", "双人", "竞速", "剧情"];
  categoryRow.innerHTML = categories.map((name) => `<div class="category-pill">${name}</div>`).join("");

  rankingList.innerHTML = rankingData
    .map(
      (item, idx) => `
      <article class="rank-item">
        <div class="rank-num">${idx + 1}</div>
        <div class="rank-info">
          <h3>${item.name}</h3>
          <p>${item.tag} · 高完播率</p>
        </div>
        <div class="rank-score">${item.score}</div>
      </article>
    `
    )
    .join("");

  creatorSpotlight.innerHTML = `
    <h3>创作者聚光灯：@MikaLab</h3>
    <p>最近 7 天发布 4 款小游戏，平均 35 秒进入首个爽点，关注后可优先收到新作推送。</p>
  `;
}

function renderProfile() {
  myGamesContainer.innerHTML = myGames
    .map(
      (game) => `
      <article class="library-card">
        <div>
          <h3>${game.name}</h3>
          <p>${game.desc}</p>
        </div>
        <button class="ghost-btn">管理</button>
      </article>
    `
    )
    .join("");

  historyStrip.innerHTML = historyGames
    .map(
      (item) => `
      <article class="history-item">
        <strong>${item.name}</strong>
        <span>${item.info}</span>
      </article>
    `
    )
    .join("");
}

function bindTabs() {
  navItems.forEach((btn) => {
    btn.addEventListener("click", () => {
      const target = btn.dataset.target;
      if (!target) return;

      navItems.forEach((item) => item.classList.remove("active"));
      btn.classList.add("active");

      tabPanels.forEach((panel) => {
        panel.classList.toggle("active", panel.dataset.tab === target);
      });

      if (target === "feed") {
        renderFeed();
      } else if (activeRuntime) {
        activeRuntime.stop();
        activeRuntime = null;
      }
    });
  });
}

function init() {
  renderFeed();
  mountSwipeEvents();

  prevGameBtn.addEventListener("click", () => switchGame(-1));
  nextGameBtn.addEventListener("click", () => switchGame(1));

  renderChips();
  bindChipEvents();
  updatePreviewTags(["点击", "躲避", "收集", activeStyle, activeDifficulty]);
  generateBtn.addEventListener("click", simulateGeneration);

  renderDiscover();
  renderProfile();
  bindTabs();

  setTimeout(() => {
    tipToast.style.display = "none";
  }, 4700);
}

init();
